/**
 * Full expert prompt bodies, keyed by role id.
 *
 * Host-only on purpose: the browser bundle imports agency-role-seeds.ts, so
 * shipping this file to the client would add ~1 MB of prompt text the panel
 * never renders (it fetches one body on demand instead).
 *
 * The payload is Brotli-compressed and base64-encoded because it is pure data:
 * readable text cost ~620 KB per copy (source plus the committed build output)
 * for content the host only reads. Use `node scripts/role-prompts.mjs --decode`
 * to inspect or edit it, and `--encode <file>` to write it back.
 */
import { brotliDecompressSync } from 'node:zlib';
const PACKED = "";
export const AGENCY_ROLE_PROMPTS = JSON.parse(brotliDecompressSync(Buffer.from(PACKED, 'base64')).toString('utf8'));
